    private sealed class ArchiveBudget { public long Bytes { get; set; } }

    private static async Task WriteSectionAsync<T>(ZipArchive archive, string name, IQueryable<T> rows,
        Dictionary<string, int> counts, ArchiveBudget budget, CancellationToken cancellationToken) {
        await using Stream stream = await archive.CreateEntry(name + ".json").OpenAsync(cancellationToken);
        await using var writer = new Utf8JsonWriter(stream);
        writer.WriteStartArray();
        int count = 0;
        await foreach (T row in rows.AsAsyncEnumerable().WithCancellation(cancellationToken)) {
            long before = writer.BytesCommitted + writer.BytesPending;
            JsonSerializer.Serialize(writer, row, JsonOptions);
            budget.Bytes += writer.BytesCommitted + writer.BytesPending - before;
            count++;
            if (budget.Bytes > MaximumUncompressedBytes) { throw new PersonalDataArchiveLimitException(); }
            await writer.FlushAsync(cancellationToken);
        }
        writer.WriteEndArray();
        await writer.FlushAsync(cancellationToken);
        counts.Add(name, count);
    }
